cd /srv/rl-env; .venv/bin/ormaos tree r1 --json --depth 100 --limit 5000 > /tmp/t.json; python3 - <<'E'
import json,collections
d=json.load(open('/tmp/t.json'))
n=d['nodes'];print(len(n), {k:v for k,v in d.items() if k!='nodes'})
print(collections.Counter(x['fn'] for x in n))
# reconstruct by depth order
stack=[];eps=[];before=after=0
for x in n:
    dp=x['depth']
    stack=stack[:dp];stack.append(x);x['ch']=[]
    if dp>0: stack[dp-1]['ch'].append(x)
for x in n:
    if x['fn']=='GridEnv.step':
        fs=[c['fn'] for c in x['ch']]
        if 'GridEnv._reward' in fs and 'GridEnv._move' in fs:
            if fs.index('GridEnv._reward')<fs.index('GridEnv._move'): before+=1
            else: after+=1
        else: print('odd',fs)
    if x['fn']=='run_episode':
        eps.append(sum(c['fn']=='GridEnv.step' for c in x['ch']))
print(before,after,eps,min(eps),max(eps))
E

